"""Gains from adding NEW patients (bulk-only, generated by PBISC) to the Real ESKD COVID scRNA cohort.
Extension design: Real 39 patients (Real values) + 29 PBISC-only patients (PBISC values); each feature rank-INT
within source; the 28 shared patients contribute Real data only (no double counting).
Outputs -> data/*.csv"""
import numpy as np, pandas as pd, warnings, sys; warnings.filterwarnings('ignore')
from scipy import stats
from statsmodels.stats.multitest import multipletests
rng=np.random.default_rng(2026)
import os
os.makedirs('data',exist_ok=True)
RUN=os.environ.get('RUN','/home/claude/run/'); FIG=os.environ.get('FIG','/home/claude/fig/')  # s02 outputs (RUN/out) and s06/s07 outputs (FIG/data_v3)
S=pd.read_csv(RUN+'out/sample_level_composition_metadata.csv')
FEATS=['rare_NK CD56 bright_pct','rare_B_ASC_dividing_pct','rare_HSPC_pct']
def patient_table(src):  # identical to Figure 7 ver3 (v3_composition.py): COVID+, primary scope, samples with >=200 cells, patient mean
    d=S[(S.source==src)&(S.condition=='positive')&S.in_primary_scope.astype(bool)&S.qc_pass_min200cells.astype(bool)]
    g=d.groupby('patient_id'); T=g[FEATS].mean(); T['severity_ord']=g.severity_ord.first(); T['fatal_harmonized']=g.fatal_harmonized.first(); return T
R=patient_table('Real'); B=patient_table('PBISC'); new=B.loc[~B.index.isin(R.index)]
print('Real',len(R),'PBISC',len(B),'new',len(new),'deaths',R.fatal_harmonized.sum(),new.fatal_harmonized.sum())
FE={'rare_NK CD56 bright_pct':'NK CD56bright','rare_B_ASC_dividing_pct':'B ASC dividing','rare_HSPC_pct':'HSPC'}
def rint(x):
    x=pd.Series(x,dtype=float); r=x.rank(); n=x.notna().sum(); return pd.Series(stats.norm.ppf((r-0.5)/n),index=x.index)
def ext(f):
    a=pd.DataFrame({'y':rint(R[f]),'sev':R.severity_ord,'fatal':R.fatal_harmonized,'src':'Real'}); b=pd.DataFrame({'y':rint(new[f]),'sev':new.severity_ord,'fatal':new.fatal_harmonized,'src':'PBISC new'})
    return a,b,pd.concat([a,b])
def boot_rho(d,nb=2000):
    v=[]; idx=np.arange(len(d))
    for _ in range(nb):
        s=d.iloc[rng.choice(idx,len(d))]; v.append(stats.spearmanr(s.sev,s.y)[0])
    return np.nanpercentile(v,[2.5,97.5])
def auc(d):
    a=d.y[d.fatal==1]; b=d.y[d.fatal==0]; u=stats.mannwhitneyu(a,b); return u.statistic/len(a)/len(b),u.pvalue
def boot_auc(d,nb=2000):
    v=[]; f=d[d.fatal==1]; s=d[d.fatal==0]
    for _ in range(nb):
        dd=pd.concat([f.iloc[rng.choice(len(f),len(f))],s.iloc[rng.choice(len(s),len(s))]]); v.append(auc(dd)[0])
    return np.percentile(v,[2.5,97.5])
sev_rows=[]; death_rows=[]
for f,name in FE.items():
    a,b,e=ext(f)
    for lab,d in [('Real (39)',a),('PBISC new (29)',b),('Real + PBISC new (68)',e)]:
        r,p=stats.spearmanr(d.sev,d.y); lo,hi=boot_rho(d); sev_rows.append(dict(feature=name,set=lab,n=len(d),rho=r,lo=lo,hi=hi,p=p))
        A,pa=auc(d); lo,hi=boot_auc(d); death_rows.append(dict(feature=name,set=lab,n=len(d),deaths=int(d.fatal.sum()),auc=A,lo=lo,hi=hi,p=pa))
S=pd.DataFrame(sev_rows); D=pd.DataFrame(death_rows)
for k,d in S.groupby('set'): S.loc[d.index,'q_3features']=multipletests(d.p,method='fdr_bh')[1]
for k,d in D.groupby('set'): D.loc[d.index,'q_3features']=multipletests(d.p,method='fdr_bh')[1]
S.to_csv('data/gain_severity_rho.csv',index=False); D.to_csv('data/gain_death_auc.csv',index=False)
pd.set_option('display.width',220); print(S.round(4).to_string()); print(D.round(4).to_string())
# power curves (from ver3, 1000 draws) and n for 80% power by linear interpolation
E=pd.read_csv(FIG+'data_v3/extension_power_v3.csv'); E=E[E.name.isin(['NK CD56 bright','B_ASC_dividing','HSPC','DC'])]
E.to_csv('data/gain_power_curves.csv',index=False)
def n80(x,y):
    x=np.asarray(x); y=np.asarray(y)
    if y[0]>=0.8: return x[0]
    k=np.where(y>=0.8)[0]
    if not len(k): return np.nan
    i=k[0]; return x[i-1]+(0.8-y[i-1])*(x[i]-x[i-1])/(y[i]-y[i-1])
rows=[]
for nm,d in E.groupby('name'):
    rows.append(dict(feature=nm,n80_real_alone=n80(d.n_real,d.real_alone),n80_plus_new=n80(d.n_real,d.plus_pbisc_only),n80_plus_shuffled=n80(d.n_real,d.plus_shuffled_pbisc),
                     power_at20_real=float(d[d.n_real==20].real_alone),power_at20_new=float(d[d.n_real==20].plus_pbisc_only),power_at20_shuffled=float(d[d.n_real==20].plus_shuffled_pbisc)))
N=pd.DataFrame(rows); N.to_csv('data/gain_n80.csv',index=False); print(N.round(3).to_string())
# deconvolution vs PBISC on the SAME 29 new patients (same bulk input)
Dc=pd.read_csv(FIG+'data_v3/deconvolution_vs_pbisc_severity_v3.csv')
Dc=Dc[Dc.feature.isin(['rare_NK CD56 bright_pct','rare_B_ASC_dividing_pct'])&Dc.method.isin(['deconvolution (uncalibrated)','deconvolution (calibrated)','PBISC'])]
Dc.to_csv('data/gain_deconvolution_new_patients.csv',index=False); print(Dc[['method','feature','rho_new_patients','p_new_patients']].round(3).to_string())
Acc=pd.read_csv(FIG+'data_v3/deconvolution_accuracy_matched_v3.csv'); Acc[Acc.feature.isin(['rare_NK CD56 bright_pct','rare_B_ASC_dividing_pct'])].to_csv('data/gain_deconvolution_accuracy.csv',index=False)
